package com.arena.core.training;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.http.*;
@RestController @RequestMapping("/api/academy/staff") @RequiredArgsConstructor
@io.swagger.v3.oas.annotations.tags.Tag(name="Staff login access")
public class StaffRegistrationController {
 private final StaffRegistrationService registrations;
 @io.swagger.v3.oas.annotations.Operation(summary="Register staff with login access",description="Owner or Full Operations Manager only, with existing personnel-role restrictions. Required requestId is an academy-scoped idempotency key. A durable inactive intent precedes Keycloak provisioning; membership activates only after the local identity link commits. Retry identical payloads with the same requestId. Notification failure returns the committed member with notificationState FAILED, not a failed create. No existing Keycloak identity is adopted or deleted.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.DUPLICATE_USERNAME,com.arena.core.exception.ErrorCode.DUPLICATE_EMAIL,com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.RESOURCE_NOT_FOUND,com.arena.core.exception.ErrorCode.INVALID_STATE,com.arena.core.exception.ErrorCode.IDENTITY_PROVIDER_UNAVAILABLE,com.arena.core.exception.ErrorCode.IDENTITY_CREATION_FAILED,com.arena.core.exception.ErrorCode.STAFF_REGISTRATION_UNCERTAIN,com.arena.core.exception.ErrorCode.USER_ALREADY_EXISTS,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED})
 @PostMapping("/registration") @ResponseStatus(HttpStatus.CREATED) public ResponseEntity<AcademyStaff> register(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody StaffRegistrationService.Registration request){return ResponseEntity.status(HttpStatus.CREATED).cacheControl(CacheControl.noStore()).body(registrations.register(jwt,request));}
 @io.swagger.v3.oas.annotations.Operation(summary="Validate proposed staff login identifiers",description="Authenticated Owner or Full Operations Manager only. Case-insensitive username/email validation against local accounts, reserved staff intents and the configured Keycloak realm. Does not return identity/profile data. Never an anonymous lookup. An owned requestId/staffId may permit recovery of that exact pending membership.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.DUPLICATE_USERNAME,com.arena.core.exception.ErrorCode.DUPLICATE_EMAIL,com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.RESOURCE_NOT_FOUND,com.arena.core.exception.ErrorCode.INVALID_STATE,com.arena.core.exception.ErrorCode.IDENTITY_PROVIDER_UNAVAILABLE,com.arena.core.exception.ErrorCode.IDENTITY_CREATION_FAILED,com.arena.core.exception.ErrorCode.STAFF_REGISTRATION_UNCERTAIN,com.arena.core.exception.ErrorCode.USER_ALREADY_EXISTS,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED})
 @PostMapping("/login-availability") public ResponseEntity<java.util.Map<String,Boolean>> available(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody StaffRegistrationService.Availability request){registrations.available(jwt,request);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(java.util.Map.of("available",true));}
 @io.swagger.v3.oas.annotations.Operation(summary="Retry an incomplete login-enabled staff registration",description="Authorized tenant-scoped recovery from the persisted inactive intent, using its original immutable request payload and ownership markers. Does not create another membership or adopt an unrelated identity.")
 @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.DUPLICATE_USERNAME,com.arena.core.exception.ErrorCode.DUPLICATE_EMAIL,com.arena.core.exception.ErrorCode.CONFLICT,com.arena.core.exception.ErrorCode.RESOURCE_NOT_FOUND,com.arena.core.exception.ErrorCode.INVALID_STATE,com.arena.core.exception.ErrorCode.IDENTITY_PROVIDER_UNAVAILABLE,com.arena.core.exception.ErrorCode.IDENTITY_CREATION_FAILED,com.arena.core.exception.ErrorCode.STAFF_REGISTRATION_UNCERTAIN,com.arena.core.exception.ErrorCode.USER_ALREADY_EXISTS,com.arena.core.exception.ErrorCode.CUSTOMER_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.SUBSCRIPTION_ACCESS_BLOCKED,com.arena.core.exception.ErrorCode.PAYMENT_REQUIRED})
 @PostMapping("/{id}/registration/retry") public ResponseEntity<AcademyStaff> retry(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(registrations.retry(jwt,id));}
}
